// Where the committed migrations are (packages/db/drizzle, generated by `pnpm --filter @samite/db generate`).
// A separate entry so the web app's bundle never resolves the folder: migrations are run by the worker on start,
// by the local harness, and by tests, never by the web app.
import { fileURLToPath } from "node:url"
import { migrateDb, type Db } from "./index"

export const MIGRATIONS_DIR = fileURLToPath(new URL("../drizzle", import.meta.url))
export const migrate = (db: Db) => migrateDb(db, MIGRATIONS_DIR)
